const crypto = require('crypto');
const http = require('http');
const { DOMParser } = require('@xmldom/xmldom');

// Configuration for XML-based key exchange protocol
const PARSER_FEATURES = {
  locator: true,
  normalize: true
};

class KeyExchangeProtocol {
  constructor(options = {}) {
    this.privateKey = crypto.generateKeyPairSync('rsa', {
      modulusLength: 2048,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
    });
    this.trustedPeers = new Map();
    this.nonceStore = new Set();
    this.parserConfig = this._buildParserConfig(options);
  }

  _buildParserConfig(options) {
    // Build parser configuration from protocol options
    const config = { ...PARSER_FEATURES };

    // Protocol v2 requires strict parsing - no entity resolution
    // Legacy key servers must upgrade to inline key material
    if (options.protocolVersion !== 1) {
      config.entityResolver = this._resolveEntity.bind(this);
    }

    return config;
  }

  _resolveEntity(publicId, systemId) {
    // Block all external entity resolution - return empty string
    // regardless of what systemId contains
    return '';
  }

  parseKeyExchangeMessage(xmlPayload, peerAddress) {
    // Validate the peer is from trusted reverse proxy
    if (!this._validatePeerOrigin(peerAddress)) {
      throw new Error('Untrusted peer origin');
    }

    // Strip DOCTYPE declarations to prevent XXE entirely
    const sanitized = xmlPayload.replace(/<!DOCTYPE[^>]*>/gi, '');

    const parser = new DOMParser(this.parserConfig);
    const doc = parser.parseFromString(sanitized, 'application/xml');

    const errors = doc.getElementsByTagName('parsererror');
    if (errors.length > 0) {
      throw new Error('Malformed key exchange XML');
    }

    return this._extractKeyMaterial(doc);
  }

  _extractKeyMaterial(doc) {
    const keyExchange = doc.documentElement;
    if (!keyExchange || keyExchange.tagName !== 'KeyExchange') {
      throw new Error('Invalid root element');
    }

    const nonceEl = keyExchange.getElementsByTagName('Nonce')[0];
    const pubKeyEl = keyExchange.getElementsByTagName('PublicKey')[0];
    const sigEl = keyExchange.getElementsByTagName('Signature')[0];

    if (!nonceEl || !pubKeyEl || !sigEl) {
      throw new Error('Missing required key exchange elements');
    }

    const nonce = nonceEl.textContent;
    const publicKey = pubKeyEl.textContent;
    const signature = sigEl.textContent;

    // Replay protection
    if (this.nonceStore.has(nonce)) {
      throw new Error('Nonce replay detected');
    }

    // Verify signature over nonce + public key BEFORE trusting the material
    const verifier = crypto.createVerify('SHA256');
    verifier.update(nonce + publicKey);
    verifier.end();

    let signatureValid = false;
    try {
      signatureValid = verifier.verify(publicKey, signature, 'base64');
    } catch (err) {
      throw new Error('Invalid signature or key material');
    }

    if (!signatureValid) {
      throw new Error('Signature verification failed');
    }

    // Only record nonce after successful verification
    this.nonceStore.add(nonce);

    // Return extracted material for further processing
    return { nonce, publicKey, signature };
  }

  _validatePeerOrigin(peerAddress) {
    // Only accept connections forwarded by our reverse proxy
    const trustedProxies = ['127.0.0.1', '::1', '10.0.0.1'];
    return trustedProxies.includes(peerAddress);
  }
}

// HTTP server behind nginx reverse proxy
function createServer(options = {}) {
  const protocol = new KeyExchangeProtocol(options);

  return http.createServer((req, res) => {
    if (req.method !== 'POST' || req.url !== '/api/v2/key-exchange') {
      res.writeHead(404);
      res.end();
      return;
    }

    // Get real client IP from proxy headers
    const peerAddress = req.socket.remoteAddress;

    let body = '';
    req.on('data', chunk => {
      body += chunk;
      if (body.length > 16384) {
        req.destroy();
      }
    });

    req.on('end', () => {
      try {
        const result = protocol.parseKeyExchangeMessage(body, peerAddress);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'accepted', nonce: result.nonce }));
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: err.message }));
      }
    });
  });
}

const server = createServer({ protocolVersion: 2 });
server.listen(8443, '127.0.0.1', () => {
  console.log('Key exchange service listening on 127.0.0.1:8443');
});

module.exports = { KeyExchangeProtocol, createServer };
